private static long interpolateMillis(long t1, long v1mh, long t2, long v2mh, long t) {
    BigInteger dv = BigInteger.valueOf(v2mh - v1mh);
    BigInteger dt = BigInteger.valueOf(t - t1);
    BigInteger den = BigInteger.valueOf(t2 - t1);
    BigInteger num = dv.multiply(dt);
    BigInteger q = num.divide(den);
    BigInteger r = num.remainder(den);
    if (r.shiftLeft(1).compareTo(den) >= 0) q = q.add(BigInteger.ONE);
    return MeterUnits.milliHoursToMillis(v1mh + q.longValueExact());
}
